class Solution {
    public java.util.List<java.util.List<String>> printTree(TreeNode root) {
        int height = getHeight(root) - 1;
        int rows = height + 1;
        int cols = (1 << (height + 1)) - 1;
        java.util.List<java.util.List<String>> res = new java.util.ArrayList<>();
        for (int r = 0; r < rows; r++) {
            java.util.List<String> row = new java.util.ArrayList<>();
            for (int c = 0; c < cols; c++) {
                row.add("");
            }
            res.add(row);
        }
        fill(res, root, 0, (cols - 1) / 2, height);
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void fill(java.util.List<java.util.List<String>> res, TreeNode node, int r, int c, int height) {
        if (node == null) {
            return;
        }
        res.get(r).set(c, String.valueOf(node.val));
        if (r == height) {
            return;
        }
        int offset = 1 << (height - r - 1);
        fill(res, node.left, r + 1, c - offset, height);
        fill(res, node.right, r + 1, c + offset, height);
    }
}

class Solution {
    public java.util.List<java.util.List<String>> printTree(TreeNode root) {
        int height = getHeight(root) - 1;
        int rows = height + 1;
        int cols = (1 << (height + 1)) - 1;
        java.util.List<java.util.List<String>> res = new java.util.ArrayList<>();
        for (int r = 0; r < rows; r++) {
            java.util.List<String> row = new java.util.ArrayList<>();
            for (int c = 0; c < cols; c++) {
                row.add("");
            }
            res.add(row);
        }

        java.util.Queue<TreeNode> nodeQ = new java.util.ArrayDeque<>();
        java.util.Queue<int[]> posQ = new java.util.ArrayDeque<>();
        nodeQ.offer(root);
        posQ.offer(new int[]{0, (cols - 1) / 2});
        while (!nodeQ.isEmpty()) {
            TreeNode node = nodeQ.poll();
            int[] pos = posQ.poll();
            int r = pos[0];
            int c = pos[1];
            res.get(r).set(c, String.valueOf(node.val));
            if (r == height) {
                continue;
            }
            int offset = 1 << (height - r - 1);
            if (node.left != null) {
                nodeQ.offer(node.left);
                posQ.offer(new int[]{r + 1, c - offset});
            }
            if (node.right != null) {
                nodeQ.offer(node.right);
                posQ.offer(new int[]{r + 1, c + offset});
            }
        }
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }
}

class Solution {
    public java.util.List<java.util.List<String>> printTree(TreeNode root) {
        int height = height(root);
        int rows = height;
        int cols = (1 << height) - 1;
        java.util.List<java.util.List<String>> answer = new java.util.ArrayList<>();
        for (int r = 0; r < rows; r++) {
            java.util.List<String> row = new java.util.ArrayList<>();
            for (int c = 0; c < cols; c++) {
                row.add("");
            }
            answer.add(row);
        }
        place(root, 0, 0, cols - 1, answer);
        return answer;
    }

    private int height(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }

    private void place(TreeNode node, int row, int left, int right,
                       java.util.List<java.util.List<String>> answer) {
        if (node == null || left > right) {
            return;
        }
        int mid = (left + right) >>> 1;
        answer.get(row).set(mid, String.valueOf(node.val));
        place(node.left, row + 1, left, mid - 1, answer);
        place(node.right, row + 1, mid + 1, right, answer);
    }
}

class Solution {
    public java.util.List<java.util.List<String>> printTree(TreeNode root) {
        int height = getHeight(root) - 1;
        int rows = height + 1;
        int cols = (1 << (height + 1)) - 1;
        java.util.List<Placement> placements = new java.util.ArrayList<>();
        collect(root, 0, (cols - 1) / 2, height, placements);

        java.util.List<java.util.List<String>> res = new java.util.ArrayList<>();
        for (int r = 0; r < rows; r++) {
            java.util.List<String> row = new java.util.ArrayList<>();
            for (int c = 0; c < cols; c++) {
                row.add("");
            }
            res.add(row);
        }
        for (Placement placement : placements) {
            res.get(placement.row).set(placement.col, placement.value);
        }
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void collect(TreeNode node, int row, int col, int height, java.util.List<Placement> placements) {
        if (node == null) {
            return;
        }
        placements.add(new Placement(row, col, String.valueOf(node.val)));
        if (row == height) {
            return;
        }
        int offset = 1 << (height - row - 1);
        collect(node.left, row + 1, col - offset, height, placements);
        collect(node.right, row + 1, col + offset, height, placements);
    }

    private static final class Placement {
        final int row;
        final int col;
        final String value;

        Placement(int row, int col, String value) {
            this.row = row;
            this.col = col;
            this.value = value;
        }
    }
}
